def toggle_system():
    if st.session_state.run:
        st.session_state.run = False
        if 'cap' in st.session_state and st.session_state.cap is not None:
            st.session_state.cap.release()
            st.session_state.cap = None
    else:
        st.session_state.run = True

def handle_crash():
    if not st.session_state.frame_buffer:
        return
        
    # Stop the camera
    st.session_state.run = False
    if 'cap' in st.session_state and st.session_state.cap is not None:
        st.session_state.cap.release()
        st.session_state.cap = None

    buffer_data = list(st.session_state.frame_buffer)
    if not buffer_data:
        return
        
    # Calculate true FPS to prevent fast-motion effect
    start_time = buffer_data[0][0]
    end_time = buffer_data[-1][0]
    duration = end_time - start_time
    actual_fps = len(buffer_data) / duration if duration > 0 else 15.0
    
    frames = [data[1] for data in buffer_data]
        
    # Compile MP4
    height, width, _ = frames[0].shape
    fourcc = cv2.VideoWriter_fourcc(*'avc1') # Changed to H.264 for HTML5 web browser compatibility
    out = cv2.VideoWriter('accident_incident_report.mp4', fourcc, actual_fps, (width, height))
    for f in frames:
        out.write(f)
    out.release()
    
    # Encrypt the MP4
    key = Fernet.generate_key()
    fernet = Fernet(key)
    
    with open('accident_incident_report.mp4', 'rb') as f:
        original_data = f.read()
        
    encrypted_data = fernet.encrypt(original_data)
    
    st.session_state.crash_key = key.decode()
    st.session_state.crash_report_data = encrypted_data
    st.session_state.crash_report_raw = original_data
    st.session_state.crash_report_ready = True
    st.session_state.frame_buffer.clear()
    
    # Clean up local unencrypted file
    if os.path.exists('accident_incident_report.mp4'):
        os.remove('accident_incident_report.mp4')

st.sidebar.button("Start Monitor" if not st.session_state.run else "Stop Monitor", on_click=toggle_system, use_container_width=True)
st.sidebar.button("🚨 CRASH DETECTED", type="primary", on_click=handle_crash, use_container_width=True)

